window.CUES=[{"start": 8.6, "end": 14.4, "text": "Setiap pelatihan memiliki perjalanan yang perlu diperhatikan. Ada peserta yang mengikuti kegiatan, kehadiran"}, {"start": 14.55, "end": 20.35, "text": "yang perlu dicatat, serta perkembangan yang perlu dinilai. Setelah sesi selesai, informasi tersebut"}, {"start": 20.5, "end": 26.300000000000004, "text": "menjadi bahan untuk meninjau pelaksanaan dan menyusun laporan. Bagaimana seluruh proses ini dapat"}, {"start": 26.450000000000003, "end": 32.25, "text": "dipantau dengan lebih tertata?"}, {"start": 33.6, "end": 39.400000000000006, "text": "Inilah Monitoring Pelatihan Pegawai, dashboard pendukung pengelolaan pelatihan di Pusat Pengembangan Aparatur Komdigi."}, {"start": 39.550000000000004, "end": 45.35, "text": "Melalui satu alur aplikasi, informasi program, peserta, kehadiran dan evaluasi dapat ditelusuri sesuai"}, {"start": 45.5, "end": 51.300000000000004, "text": "akses pengguna. Admin Pelatihan, Petugas Kelas dan Pengajar menjalankan perannya masing-masing, dengan informasi"}, {"start": 51.45, "end": 57.25000000000001, "text": "yang saling mendukung sepanjang kegiatan."}, {"start": 58.6, "end": 65.21, "text": "Perjalanan dimulai dari persiapan. Admin menyiapkan program, menentukan Jenjang dan sesi, lalu mendaftarkan"}, {"start": 65.36, "end": 71.97, "text": "peserta pada kelas yang sesuai. Penugasan Petugas Kelas dan Pengajar membantu membagi tanggung"}, {"start": 72.12, "end": 78.72999999999999, "text": "jawab pelaksanaan. Saat program dipilih, informasi yang ditampilkan mengikuti konteks kegiatan tersebut. Susunan"}, {"start": 78.88, "end": 85.49, "text": "ini membantu pengguna mengetahui kelas yang sedang ditangani, peserta yang terdaftar, dan sesi"}, {"start": 85.64, "end": 92.25, "text": "yang akan dilaksanakan."}, {"start": 93.6, "end": 99.91666666666666, "text": "Saat sesi berlangsung, Petugas Kelas dapat menyiapkan presensi melalui QR. Peserta membuka tautan"}, {"start": 100.06666666666666, "end": 106.38333333333333, "text": "dari pemindaian, lalu mencatat kedatangan atau kepulangan sesuai jenis presensi. Untuk pelaksanaan yang"}, {"start": 106.53333333333333, "end": 112.85, "text": "memerlukan pencatatan oleh petugas, tersedia presensi manual. Status hadir, terlambat, sakit, izin, atau"}, {"start": 113.0, "end": 119.31666666666665, "text": "tanpa keterangan dipilih sesuai keadaan peserta. Setelah pencatatan disimpan dan data dimuat ulang,"}, {"start": 119.46666666666665, "end": 125.78333333333332, "text": "hasilnya dapat diperiksa pada Monitoring. Informasi izin dan bukti pendukung juga membantu petugas"}, {"start": 125.93333333333332, "end": 132.24999999999997, "text": "menelusuri keadaan peserta selama kegiatan."}, {"start": 133.6, "end": 139.91666666666666, "text": "Setelah kegiatan, Pengajar menilai peserta berdasarkan pengamatan selama sesi. Enam aspek mencakup keaktifan,"}, {"start": 140.06666666666666, "end": 146.38333333333333, "text": "kedisiplinan, kerapian, kesopanan, kreativitas dan kerja sama. Nilai serta catatan disimpan melalui formulir"}, {"start": 146.53333333333333, "end": 152.85, "text": "evaluasi. Admin atau Petugas Kelas juga mengisi evaluasi Panitia, yang berfokus pada kedisiplinan,"}, {"start": 153.0, "end": 159.31666666666666, "text": "kerja sama dan prakarsa. Kejadian sikap dan perilaku dicatat melalui bagian tersendiri. Setiap"}, {"start": 159.46666666666667, "end": 165.78333333333333, "text": "sumber tetap dapat dibedakan, sehingga hasil penilaian memiliki konteks yang jelas untuk ditinjau"}, {"start": 165.93333333333334, "end": 172.24999999999997, "text": "oleh pihak yang berwenang."}, {"start": 173.6, "end": 180.20999999999998, "text": "Dari pencatatan tersebut, Admin dapat memeriksa kelengkapan data dan menjalankan perhitungan jam pelajaran"}, {"start": 180.35999999999999, "end": 186.97, "text": "atau JP. Rekap Program membantu membaca hasil kehadiran, catatan perilaku dan nilai evaluasi"}, {"start": 187.12, "end": 193.73, "text": "peserta beserta statusnya. Data dapat diunduh dalam CSV untuk kebutuhan pengolahan lebih lanjut."}, {"start": 193.88, "end": 200.48999999999998, "text": "Setelah program selesai, laporan program dapat disusun melalui sistem sebagai bahan pendukung peninjauan."}, {"start": 200.64, "end": 207.24999999999997, "text": "Hasilnya membantu penanggung jawab memahami pelaksanaan dan mengambil keputusan sesuai kewenangannya."}, {"start": 208.6, "end": 214.39999999999998, "text": "Manfaat dashboard berlanjut setelah pelatihan selesai. Riwayat yang tersimpan membantu penelusuran kegiatan dan"}, {"start": 214.54999999999998, "end": 220.35, "text": "pemeriksaan kembali saat dibutuhkan. Rekap serta laporan dapat menjadi bahan evaluasi dan pertimbangan"}, {"start": 220.5, "end": 226.29999999999998, "text": "untuk merencanakan pelatihan berikutnya. Dengan pencatatan yang konsisten dan pembagian tugas yang jelas,"}, {"start": 226.45, "end": 232.25, "text": "pengelolaan informasi dapat diteruskan untuk mendukung kebutuhan instansi dalam jangka panjang."}, {"start": 233.6, "end": 240.35, "text": "Monitoring Pelatihan Pegawai. Mendukung perjalanan pelatihan, dari persiapan hingga evaluasi. Pelatihan terpantau, data"}, {"start": 240.5, "end": 247.25, "text": "tertata, dan informasi siap menjadi bahan tindak lanjut. Pusat Pengembangan Aparatur Komdigi."}]
;
